<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/system.php';
header('Content-Type: application/json; charset=utf-8');
function reviewOut($ok,$message='',$data=[],$code=200){http_response_code($code);echo json_encode(['ok'=>$ok,'message'=>$message,'data'=>$data],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
if(!isLoggedIn())reviewOut(false,'Please sign in.',[],401);
$pdo=getDBConnection();try{qps_ensure_aux_schema($pdo);qps_ensure_question_draft_schema($pdo);}catch(Throwable $e){reviewOut(false,'Schema initialization failed: '.$e->getMessage(),[],500);}
$user=getCurrentUser()?:[];$reviewer=(string)($user['staff_code']??'');$role=isCOE()?'COE':(isHOD()?'HOD':'');if($role==='')reviewOut(false,'HOD or COE access required.',[],403);
$action=(string)($_POST['action']??$_GET['action']??'list');
try{
 if($action==='list'){
  $status=$role==='HOD'?'SUBMITTED_TO_HOD':'SUBMITTED_TO_COE';
  $sql='SELECT d.* FROM qps_question_bank_drafts d WHERE d.status=?';$args=[$status];
  if($role==='HOD'){$dept=trim((string)($user['dept_code']??''));if($dept!==''){$sql.=' AND UPPER(COALESCE(d.dept_code,""))=UPPER(?)';$args[]=$dept;}}
  $sql.=' ORDER BY d.submitted_at ASC,d.id ASC';$st=$pdo->prepare($sql);$st->execute($args);$drafts=$st->fetchAll();
  foreach($drafts as &$d){$q=$pdo->prepare('SELECT * FROM qps_question_bank_draft_questions WHERE draft_id=? ORDER BY section_type,q_number,id');$q->execute([$d['id']]);$d['questions']=$q->fetchAll();}unset($d);reviewOut(true,'Review queue loaded.',['drafts'=>$drafts,'role'=>$role]);
 }
 $draftId=(int)($_POST['draft_id']??0);$st=$pdo->prepare('SELECT * FROM qps_question_bank_drafts WHERE id=?');$st->execute([$draftId]);$draft=$st->fetch();if(!$draft)reviewOut(false,'Draft not found.',[],404);
 $expected=$role==='HOD'?'SUBMITTED_TO_HOD':'SUBMITTED_TO_COE';if($draft['status']!==$expected)reviewOut(false,'This draft is not waiting in your review queue.',[],409);
 if($role==='HOD' && !empty($user['dept_code']) && strtoupper((string)$draft['dept_code'])!==strtoupper((string)$user['dept_code']) && !isERPStaff())reviewOut(false,'This bank belongs to another department.',[],403);
 if($action==='review_question'){
  $qid=(int)($_POST['question_id']??0);$decision=strtoupper(trim((string)($_POST['decision']??'')));$remarks=trim((string)($_POST['remarks']??''));if(!in_array($decision,['VERIFIED','CORRECTION_REQUIRED'],true))reviewOut(false,'Invalid question decision.',[],422);if($decision==='CORRECTION_REQUIRED'&&$remarks==='')reviewOut(false,'Enter correction remarks for the staff member.',[],422);
  $q=$pdo->prepare('SELECT * FROM qps_question_bank_draft_questions WHERE id=? AND draft_id=?');$q->execute([$qid,$draftId]);$question=$q->fetch();if(!$question)reviewOut(false,'Question does not belong to this bank.',[],404);
  $pdo->beginTransaction();$pdo->prepare('UPDATE qps_question_bank_draft_questions SET review_status=?,review_remarks=? WHERE id=?')->execute([$decision,$remarks?:null,$qid]);$pdo->prepare('INSERT INTO qps_question_review_history(draft_id,draft_question_id,reviewer_code,reviewer_role,decision,remarks,snapshot_json) VALUES(?,?,?,?,?,?,?)')->execute([$draftId,$qid,$reviewer,$role,$decision,$remarks,json_encode($question,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);if($decision==='CORRECTION_REQUIRED'){$returnStatus=$role==='HOD'?'RETURNED_BY_HOD':'RETURNED_BY_COE';$pdo->prepare('UPDATE qps_question_bank_drafts SET status=?,review_comments=?,updated_at=NOW() WHERE id=?')->execute([$returnStatus,$remarks,$draftId]);}$pdo->commit();qps_activity_log($pdo,'QUESTION_REVIEW_'.$decision,'DRAFT_QUESTION',(string)$qid,['draft_id'=>$draftId,'remarks'=>$remarks]);reviewOut(true,$decision==='CORRECTION_REQUIRED'?'Question returned to staff for correction.':'Question review saved.');
 }
 if($action==='return_bank'){
  $remarks=trim((string)($_POST['remarks']??''));if($remarks==='')reviewOut(false,'Please enter bank-level remarks.',[],422);$newStatus=$role==='HOD'?'RETURNED_BY_HOD':'RETURNED_BY_COE';$pdo->beginTransaction();$pdo->prepare('UPDATE qps_question_bank_drafts SET status=?,review_comments=?,updated_at=NOW() WHERE id=?')->execute([$newStatus,$remarks,$draftId]);$pdo->prepare('INSERT INTO qps_question_review_history(draft_id,reviewer_code,reviewer_role,decision,remarks) VALUES(?,?,?,?,?)')->execute([$draftId,$reviewer,$role,'RETURN_BANK',$remarks]);$pdo->commit();qps_activity_log($pdo,'BANK_RETURNED','DRAFT',(string)$draftId,['remarks'=>$remarks,'role'=>$role]);reviewOut(true,'Bank returned for correction.');
 }
 if($action==='approve_bank'){
  $q=$pdo->prepare('SELECT * FROM qps_question_bank_draft_questions WHERE draft_id=? ORDER BY section_type,q_number,id');$q->execute([$draftId]);$questions=$q->fetchAll();if(!$questions)reviewOut(false,'This bank has no questions.',[],422);
  $bad=array_filter($questions,fn($q)=>($q['review_status']??'PENDING')!=='VERIFIED');if($bad)reviewOut(false,'Every question must be marked VERIFIED before the bank can advance.', ['unverified_count'=>count($bad)],422);
  if($role==='HOD'){$pdo->beginTransaction();$pdo->prepare("UPDATE qps_question_bank_drafts SET status='SUBMITTED_TO_COE',hod_reviewed_by=?,hod_reviewed_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$reviewer,$draftId]);$pdo->prepare('INSERT INTO qps_question_review_history(draft_id,reviewer_code,reviewer_role,decision,remarks) VALUES(?,?,?,?,?)')->execute([$draftId,$reviewer,'HOD','APPROVED_TO_COE',trim((string)($_POST['remarks']??''))]);$pdo->commit();qps_activity_log($pdo,'BANK_APPROVED_TO_COE','DRAFT',(string)$draftId,['question_count'=>count($questions)]);reviewOut(true,'HOD approval saved. Bank submitted to COE.');}
  // COE final approval: promote all records in one transaction, then clear only the temporary question rows.
  $pdo->beginTransaction();
  $payload=[];foreach($questions as $i=>$q){$payload[]=['q_number'=>$i+1,'unit_no'=>(int)$q['unit_no'],'sub_unit'=>$q['sub_unit'],'section_type'=>$q['section_type'],'question_type'=>$q['question_type'],'question_text'=>$q['question_text'],'marks'=>(int)$q['marks'],'k_level'=>$q['k_level'],'co_level'=>$q['co_level'],'options_json'=>$q['options_json'],'answer_key'=>$q['answer_key'],'match_column_a'=>$q['match_column_a'],'match_column_b'=>$q['match_column_b'],'image_url'=>$q['image_path'],'compulsory'=>(int)$q['compulsory'],'choice_group'=>$q['choice_group']];}
  $json=json_encode(['schema_version'=>'1.0','metadata'=>['staff_code'=>$draft['staff_code'],'paper_code'=>$draft['paper_code'],'course_title'=>$draft['course_title'],'semester'=>$draft['semester'],'academic_year'=>$draft['academic_year'],'exam_type'=>$draft['exam_type'],'dept_code'=>$draft['dept_code'],'approved_by'=>$reviewer],'questions'=>$payload],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
  $st=$pdo->prepare("INSERT INTO question_banks(staff_code,dept_code,dept_name,paper_code,course_title,semester,academic_year,exam_type,regulation,degree_level,max_marks,total_questions,status,review_comments,questions_json,created_at,updated_at,submitted_at,version_no,source_format,language,schema_version) VALUES(?,?,?,?,?,?,?,?,?,?,75,?,'Approved',?,?,NOW(),NOW(),NOW(),1,'FORM','en','1.0')");
  $st->execute([$draft['staff_code'],$draft['dept_code'],$draft['dept_name'],$draft['paper_code'],$draft['course_title'],$draft['semester'],$draft['academic_year'],$draft['exam_type'],$draft['regulation'],$draft['degree_level'],count($questions),$draft['review_comments'],$json]);$bankId=(int)$pdo->lastInsertId();
  $ins=$pdo->prepare('INSERT INTO questions(bank_id,course_code,q_number,unit_no,sub_unit,section_type,question_type,question_text,marks,k_level,co_level,options_json,answer_key,match_column_a,match_column_b,image_url,compulsory,choice_group,language,validation_status,import_schema) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,\'en\',\'VALID\',\'FORM\')');
  foreach($questions as $i=>$q){$ins->execute([$bankId,$draft['paper_code'],$i+1,$q['unit_no'],$q['sub_unit'],$q['section_type'],$q['question_type'],$q['question_text'],$q['marks'],$q['k_level'],$q['co_level'],$q['options_json'],$q['answer_key'],$q['match_column_a'],$q['match_column_b'],$q['image_path'],$q['compulsory']?'Yes':'No',$q['choice_group']]);}
  $pdo->prepare('INSERT INTO qps_question_review_history(draft_id,reviewer_code,reviewer_role,decision,remarks) VALUES(?,?,?,?,?)')->execute([$draftId,$reviewer,'COE','APPROVED',trim((string)($_POST['remarks']??''))]);
  $pdo->prepare("UPDATE qps_question_bank_drafts SET status='APPROVED',promoted_bank_id=?,updated_at=NOW() WHERE id=?")->execute([$bankId,$draftId]);$pdo->prepare('DELETE FROM qps_question_bank_draft_questions WHERE draft_id=?')->execute([$draftId]);try { qps_rebuild_course_matrix($pdo,(string)$draft['paper_code'],(string)$draft['semester'],(string)$draft['academic_year'],(string)$draft['exam_type'],(string)$draft['dept_code']); } catch(Throwable $matrixError) { error_log('QPS matrix refresh failed: '.$matrixError->getMessage()); }$pdo->commit();qps_activity_log($pdo,'BANK_PUBLISHED','QUESTION_BANK',(string)$bankId,['draft_id'=>$draftId,'question_count'=>count($questions)]);reviewOut(true,'COE approved the bank and promoted all questions. Draft question rows have been cleared.',['bank_id'=>$bankId,'question_count'=>count($questions)]);
 }
 reviewOut(false,'Unknown action.',[],400);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();reviewOut(false,'Review action failed: '.$e->getMessage(),[],500);}
